using Clock=chrono::steady_clock;
static int64_t nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string trim(string s){size_t a=s.find_first_not_of(" \t\r\n"), b=s.find_last_not_of(" \t\r\n");return a==string::npos?string():s.substr(a,b-a+1);}
static bool number(const string& s,uint64_t& n){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(UINT64_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return true;}
struct Config{string ip,root;int port;uint64_t maxconn,headers,header_timeout,idle_timeout,write_timeout,maxreq,pipeline;};
static bool config(int argc,char**argv,Config& c){if(argc!=3||string(argv[1])!="--config")return false;ifstream f(argv[2]);if(!f)return false;unordered_map<string,string> m;string line;while(getline(f,line)){line=trim(line);if(line.empty()||line[0]=='#')continue;auto p=line.find('=');if(p==string::npos)return false;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(k.empty()||v.empty()||m.count(k))return false;m[k]=v;}const array<string,9> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth"};if(m.size()!=keys.size())return false;for(auto &k:keys)if(!m.count(k))return false;auto l=m["listen"];auto p=l.rfind(':');if(p==string::npos)return false;c.ip=l.substr(0,p);uint64_t port;in_addr a;if(inet_pton(AF_INET,c.ip.c_str(),&a)!=1||!number(l.substr(p+1),port)||port==0||port>65535)return false;c.port=port;c.root=m["root"];if(c.root.empty()||c.root[0]!='/')return false;struct stat st;if(stat(c.root.c_str(),&st)||!S_ISDIR(st.st_mode))return false;return number(m["max_connections"],c.maxconn)&&c.maxconn&&number(m["header_bytes"],c.headers)&&c.headers&&number(m["header_timeout_ms"],c.header_timeout)&&c.header_timeout&&number(m["idle_timeout_ms"],c.idle_timeout)&&c.idle_timeout&&number(m["write_timeout_ms"],c.write_timeout)&&c.write_timeout&&number(m["max_requests"],c.maxreq)&&c.maxreq&&number(m["pipeline_depth"],c.pipeline)&&c.pipeline;}
static bool token(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||(c&&strchr("!#$%&'*+-.^_`|~",c));}
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char a=s[i++];if(a<0x80)continue;int n;unsigned x,min;if(a>=0xc2&&a<=0xdf){n=1;x=a&31;min=0x80;}else if(a>=0xe0&&a<=0xef){n=2;x=a&15;min=0x800;}else if(a>=0xf0&&a<=0xf4){n=3;x=a&7;min=0x10000;}else return false;if(i+n>s.size())return false;while(n--){unsigned char b=s[i++];if((b&0xc0)!=0x80)return false;x=(x<<6)|(b&63);}if(x<min||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
static int hex(unsigned char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
static int path_decode(string_view t,string& out){if(t.empty()||t[0]!='/')return 400;for(unsigned char c:t)if(c=='#'||c=='\\'||c==0||c<=32||c==127)return 400;size_t end=t.find('?');if(end==string_view::npos)end=t.size();out.reserve(end);for(size_t i=0;i<end;i++){unsigned char c=t[i];if(c=='%'){if(i+2>=end)return 400;int a=hex(t[i+1]),b=hex(t[i+2]);if(a<0||b<0)return 400;c=a*16+b;i+=2;}if(c==0||c=='\\')return 400;out.push_back(c);}if(!utf8(out))return 400;size_t pos=0;while(pos<out.size()){size_t e=out.find('/',pos);if(e==string::npos)e=out.size();if(out.compare(pos,e-pos,"..")==0)return 403;pos=e+1;}return 0;}
static int parse(const string& r,string& path){for(size_t i=0;i<r.size();i++){unsigned char c=r[i];if(c==0||(c=='\n'&&(i==0||r[i-1]!='\r'))||(c=='\r'&&(i+1==r.size()||r[i+1]!='\n')))return 400;}size_t e=r.find("\r\n");if(e==string::npos)return 400;string_view line(r.data(),e);size_t a=line.find(' ');if(a==string_view::npos||a==0)return 400;size_t b=line.find(' ',a+1);if(b==string_view::npos||b==a+1||line.find(' ',b+1)!=string_view::npos)return 400;for(unsigned char c:line.substr(0,a))if(!token(c))return 400;auto version=line.substr(b+1);if(version!="HTTP/1.0"&&version!="HTTP/1.1")return 400;bool cl=false;size_t pos=e+2;while(pos<r.size()){size_t q=r.find("\r\n",pos);if(q==string::npos)return 400;if(q==pos)break;string_view h(r.data()+pos,q-pos);size_t colon=h.find(':');if(colon==string_view::npos||colon==0)return 400;for(unsigned char c:h.substr(0,colon))if(!token(c))return 400;for(unsigned char c:h.substr(colon+1))if((c<32&&c!='\t')||c==127)return 400;string name(h.substr(0,colon));for(char&c:name)if(c>='A'&&c<='Z')c+=32;auto v=h.substr(colon+1);while(!v.empty()&&(v.front()==' '||v.front()=='\t'))v.remove_prefix(1);while(!v.empty()&&(v.back()==' '||v.back()=='\t'))v.remove_suffix(1);if(name=="transfer-encoding")return 400;if(name=="content-length"){if(cl||v.empty())return 400;cl=true;for(char c:v)if(c!='0')return 400;}pos=q+2;}int res=path_decode(line.substr(a+1,b-a-1),path);if(res)return res;if(line.substr(0,a)!="GET")return 405;return 0;}
static int getfile(int root,const string&path,int& fd,off_t& sz){bool trailing=path.back()=='/';size_t limit=path.size();while(limit>1&&path[limit-1]=='/')--limit;if(limit==1)return 403;int dir=root;bool owned=false;size_t pos=1;while(pos<limit){while(pos<limit&&path[pos]=='/')pos++;if(pos==limit)break;size_t end=path.find('/',pos);if(end==string::npos||end>=limit)end=limit;bool last=end==limit;string comp=path.substr(pos,end-pos);if(comp=="."){if(last){if(owned)close(dir);return 403;}pos=end+1;continue;}int flags=O_RDONLY|O_CLOEXEC|O_NOFOLLOW|O_NONBLOCK|(last?0:O_DIRECTORY);int next=openat(dir,comp.c_str(),flags);if(next<0){int err=errno;struct stat st;bool symlink=fstatat(dir,comp.c_str(),&st,AT_SYMLINK_NOFOLLOW)==0&&S_ISLNK(st.st_mode);if(owned)close(dir);if(symlink||err==ELOOP||err==EACCES||err==EPERM)return 403;return (err==ENOENT||err==ENOTDIR)?404:403;}if(owned)close(dir);if(last){struct stat st;if(fstat(next,&st)||!S_ISREG(st.st_mode)||trailing){close(next);return 403;}fd=next;sz=st.st_size;return 200;}dir=next;owned=true;pos=end+1;}if(owned)close(dir);return 403;}
struct Conn{int fd,file=-1;uint64_t id;string in,out;size_t sent=0;off_t offset=0,size=0;bool writing=false;int64_t deadline;};
struct Timer{int64_t at;int fd;uint64_t id;bool operator<(const Timer&o)const{return at>o.at;}};
static const char* reason(int s){switch(s){case 200:return "OK";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 431:return "Request Header Fields Too Large";default:return "Internal Server Error";}}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);Config cfg;if(!config(argc,argv,cfg))return 1;int root=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(root<0)return 1;int ls=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(ls<0)return 1;int one=1;setsockopt(ls,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in addr{};addr.sin_family=AF_INET;addr.sin_port=htons(cfg.port);inet_pton(AF_INET,cfg.ip.c_str(),&addr.sin_addr);if(bind(ls,(sockaddr*)&addr,sizeof(addr))||listen(ls,8192))return 1;int ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;epoll_event ev{};ev.events=EPOLLIN;ev.data.fd=ls;if(epoll_ctl(ep,EPOLL_CTL_ADD,ls,&ev))return 1;unordered_map<int,Conn> conns;priority_queue<Timer> timers;uint64_t serial=0;auto closeconn=[&](int fd){auto it=conns.find(fd);if(it==conns.end())return;epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);if(it->second.file>=0)close(it->second.file);close(fd);conns.erase(it);};auto deadline=[&](uint64_t ms){int64_t n=nowms();return ms>(uint64_t)(INT64_MAX-n)?INT64_MAX:n+(int64_t)ms;};auto respond=[&](Conn& c,int status){c.writing=true;c.deadline=deadline(cfg.write_timeout);timers.push({c.deadline,c.fd,c.id});c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(status==200?c.size:0)+"\r\nConnection: close\r\n"+(status==200?string("Content-Type: application/octet-stream\r\n"):string())+(status==405?string("Allow: GET\r\n"):string())+"\r\n";c.sent=0;};auto flush=[&](Conn& c)->bool{while(c.sent<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.sent,c.out.size()-c.sent,MSG_NOSIGNAL|(c.file>=0&&c.size?MSG_MORE:0));if(n>0)c.sent+=n;else if(n<0&&errno==EINTR)continue;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;else return false;}while(c.file>=0&&c.offset<c.size){size_t amount=(size_t)min<off_t>(c.size-c.offset,1<<20);ssize_t n=sendfile(c.fd,c.file,&c.offset,amount);if(n>0)continue;if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return true;return false;}return false;};array<epoll_event,1024> events;for(;;){int64_t now=nowms();while(!timers.empty()&&timers.top().at<=now){auto t=timers.top();timers.pop();auto it=conns.find(t.fd);if(it!=conns.end()&&it->second.id==t.id&&it->second.deadline==t.at)closeconn(t.fd);}int timeout=-1;if(!timers.empty())timeout=(int)min<int64_t>(INT_MAX,max<int64_t>(0,timers.top().at-now));int n=epoll_wait(ep,events.data(),events.size(),timeout);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){int fd=events[i].data.fd;if(fd==ls){for(;;){int client=accept4(ls,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(client<0){if(errno==EINTR)continue;break;}if(conns.size()>=cfg.maxconn){close(client);continue;}Conn c;c.fd=client;c.id=++serial;c.deadline=deadline(cfg.header_timeout);c.in.reserve((size_t)min<uint64_t>(cfg.headers,8192));auto [it,ok]=conns.emplace(client,move(c));timers.push({it->second.deadline,client,it->second.id});epoll_event x{};x.events=EPOLLIN|EPOLLRDHUP;x.data.fd=client;if(epoll_ctl(ep,EPOLL_CTL_ADD,client,&x))closeconn(client);}continue;}auto it=conns.find(fd);if(it==conns.end())continue;Conn& c=it->second;if(nowms()>=c.deadline){closeconn(fd);continue;}if(!c.writing){bool closed=false;char buf[8192];for(;;){ssize_t z=recv(fd,buf,sizeof(buf),0);if(z>0){c.in.append(buf,z);size_t end=c.in.find("\r\n\r\n");if(end!=string::npos){if(end+4>cfg.headers)respond(c,431);else{c.in.resize(end+4);string path;int status=parse(c.in,path);if(!status)status=getfile(root,path,c.file,c.size);respond(c,status);}break;}if(c.in.size()>cfg.headers){respond(c,431);break;}bool bad=false;for(size_t j=0;j<c.in.size();j++){unsigned char ch=c.in[j];if(ch==0||(ch=='\n'&&(j==0||c.in[j-1]!='\r'))||(ch=='\r'&&j+1<c.in.size()&&c.in[j+1]!='\n')){bad=true;break;}}if(bad){respond(c,400);break;}if(nowms()>=c.deadline){closed=true;break;}continue;}if(z==0){closed=true;break;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;closed=true;break;}if(closed){closeconn(fd);continue;}if(c.writing){if(!flush(c)){closeconn(fd);continue;}epoll_event x{};x.events=EPOLLOUT|EPOLLRDHUP;x.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&x);}}else{if(!flush(c)){closeconn(fd);continue;}}if(events[i].events&(EPOLLERR|EPOLLHUP)){closeconn(fd);continue;}}}return 0;}
